mapper.select:
SELECT conversation_id, user_id_1, user_id_2,
       last_message_id,
       COALESCE(last_message_time, create_time) AS last_message_time,
       create_time, update_time
FROM conversations
WHERE (user_id_1 = #{userId} OR user_id_2 = #{userId})

    AND (
        COALESCE(last_message_time, create_time) < #{cursorLastMessageTime}
        OR (
            COALESCE(last_message_time, create_time) = #{cursorLastMessageTime}
            AND conversation_id < #{cursorConversationId}
        )
    )

ORDER BY COALESCE(last_message_time, create_time) DESC, conversation_id DESC
LIMIT #{limit}
